fn is_end(self, version, _rnd, player, data, team_plan, _debug) -> bool

// --- L164: 팀 오브젝트가 아직 에픽인가 (TeamPlan::take_active(JungleType::Morgard), team_plan.rs:244->objective_target:231 인라인)
if team_plan.objective_tag != 0 { return true }        // 0 = Some(MainObjective::Morgard{..})
                                                        // None(255) 이거나 다른 오브젝트(1..11)면 즉시 종료

// --- L169
let team = player.info.team;                            // +0x930
let camp_pos: (u64,u64) = data.context.map.camp_pos(JungleType::Morgard, team == 0);

// --- L172: setup_like = TeamPlan::take_setup_like(Morgard) (team_plan.rs:258 인라인)
let setup_like = (team_plan.objective_tag == 0) && (team_plan.objective.Morgard.phase == ObjectPhase::Setup);
   // IR 은 objective_tag 를 여기서 다시 로드한다(%25). 같은 필드라 실제로는 항상 참이지만
   // LLVM 이 접지 못해 '태그!=0 -> L193 으로' 라는 죽은 경로가 블록 13->33 에 남아 있다.

// --- L173
if setup_like {
    // --- L174
    if team_plan.v24_objective_setup_should_release_to_passive(version, player, data, JungleType::Morgard) {
        return true;                                    // 셋업 단계를 접고 패시브로 풀어야 하면 종료
    }

    // --- L179: 캠프 셀에 대한 vtable+0x100 술어 (추정: 우리 팀 시야 여부)
    if game.vt_0x100(team, camp_pos.0 / 32000, camp_pos.1 / 32000) {

        // --- L180~181: 캠프에서 가장 가까운, '최근 목격된' 적 챔피언
        let nearest_to_camp_enemy: Option<&Entity> =
            cache.iter_champions(1 - team)              // cache.player_champion[1-team] (Option<&Entity> 5칸) 순회
                 .filter(|e| data.blackboard[1 - team]
                              .is_recent_visible(game/*fat ptr 2워드*/, player, e))
                 .min_by_key(|e| distance_sq(e.x, e.y, camp_pos.0, camp_pos.1));
        //  ↑ filter 술어와 key 클로저 본문은 담당 범위 밖(m10.ll 6028~6222)에 있는
        //    min_by_key 모노모피 함수 안에 있다. 거기서 Blackboard::is_recent_visible 을 호출하고,
        //    키는 Entity(+0x660,+0x668) 와 camp_pos 의 distance_sq 다.

        // --- L183
        let Some(nearest) = nearest_to_camp_enemy else { return true };  // 아무도 못 봤으면 종료

        // --- L184
        let dx = nearest.x.abs_diff(camp_pos.0);
        let dy = nearest.y.abs_diff(camp_pos.1);
        if dx*dx + dy*dy > 22500000000 { return true }  // 150000^2 초과 = 캠프 주변에 적이 없다 -> 종료
    }
}

// --- L193: 여기까지 왔으면(=오브젝트 유지 & (setup 아님 | 시야 없음 | 적이 근처)) 에픽 실체를 본다
let moba: &MobaMode = game.vt_0x40().as_moba().unwrap();   // as_moba 태그!=0 이면 unwrap_failed 패닉
let epic: Option<&Entity> = moba.jungle_runner.epic.live_list.get(0)
                                .and_then(|id| game.vt_0x1f0(*id));   // closure$2

// --- L194
if epic.is_some() { return false }                      // 에픽이 살아 있으면 플랜 유지

// 에픽이 없으면(사망/미스폰) 리스폰까지 남은 시간으로 판정
let moba = game.vt_0x40().as_moba().unwrap();           // 재호출(LLVM 이 다시 부른다)
return moba.jungle_runner.epic.next_respawn_tick.saturating_sub(game.vt_0x28())
         > data.context.setting.tick_per_second * 15;   // 15초보다 더 남았으면 종료

/* 반환 지점 요약 (블록 87 의 phi)
   pred %7  -> true   : 오브젝트가 Morgard 가 아님 (L164)
   pred %31 -> true   : v24_objective_setup_should_release_to_passive == true (L174)
   pred %56 -> true   : 최근 목격 적 챔피언이 하나도 없음 (L183)
   pred %70 -> true   : 가장 가까운 적이 캠프에서 150000 초과 (L184)
   pred %97 -> false  : 에픽 엔티티가 살아 있음 (L194)
   pred %109-> %123   : (리스폰잔여 > tick_per_second*15) (L194) */
